var owned=['projects','projects--new','project','recent','artifacts','artifacts--detail','routines','routines--new','customize','settings','settings-account','settings-devices','settings-general','settings-appearance','settings-voice','settings-notifications','settings-connections','settings-billing','settings-privacy','settings-shortcuts','settings-about','settings--sign-out','settings-billing--plan','project--empty','artifacts--empty','project--work','artifacts--code','artifacts--share','customize--profile'];function walk(l,fn){fn(l);if(l.layers)l.layers.forEach(c=>walk(c,fn));}doc.pages.filter(p=>['Proto iOS Light','Proto iOS Dark'].includes(p.name)).forEach(p=>p.layers.filter(s=>s.name.startsWith('Screen/ios/')&&owned.includes(s.name.split('/').pop())).forEach(s=>{var id=s.name.split('/').pop();walk(s,l=>{if(l.name==='segmented-control'){l.layers.forEach(q=>{if(q.style.fills.length&&q.style.fills[0].enabled){q.style.shadows=[{color:'#00000020',blur:3,x:0,y:1,spread:0,enabled:true}];}});}if(id==='artifacts--code'&&l.type==='Text'&&(l.text.startsWith('# Billing')||l.text==='webhook-rollout.md')){l.style.fontFamily='SF Mono';l.style.fontSize=l.text.startsWith('#')?14:18;l.fixedWidth=true;l.frame.width=318;}if(id==='settings-about'&&l.type==='Text'&&l.text==='PREFERENCES')l.text='WEAVE';if(id==='settings-appearance'&&l.type==='Text'&&l.text==='Follow system')l.text='Tint app icon';});var sh=s.layers.find(l=>l.name==='sheet');if(sh){var grab=sh.layers.find(l=>l.name==='grabber-wrap');grab.frame.height=14;var g=grab.layers.find(l=>l.name==='grabber');g.frame.width=60;g.frame.height=4;grab.stackLayout.apply();var tb=sh.layers.find(l=>l.name==='sheet-toolbar');tb.frame.height=70;tb.stackLayout.apply();sh.stackLayout.apply();sh.frame.y=844-sh.frame.height;}console.log(JSON.stringify({name:s.name,id:String(s.id),children:s.layers.length}));}));